function listingFacts(l){
  if(l.category==='Spaces & Property')return l.subcategory==='Lodges & Accommodation'?'Entire stay · Sleeps 4 · 2 bedrooms · Demo amenities':'Private space · Flexible dates · Demo facilities';
  if(l.category==='Transport')return l.subcategory+' · Flexible hire · Demo listing';
  if(l.category==='Services')return 'Professional service · Choose dates · Sample provider';
  if(l.category==='Hardware')return 'Equipment hire · Flexible dates · Sample inventory';
  if(l.category==='Events')return 'Event hire · Packages available · Demo listing';
  return 'Rental item · Flexible dates · Demo listing';
}
